-- Dosya      : migrations/mysql/006_inventory_order_relations.sql
-- Açıklama   : Sipariş/ödeme ilişkileri ve fiziksel stok şeması; checkout hizmeti portu değildir.
CREATE TABLE warehouses(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,name TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE inventory_balance(variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,warehouse_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,on_hand INT NOT NULL DEFAULT 0,quarantine INT NOT NULL DEFAULT 0,safety_stock INT NOT NULL DEFAULT 0,minimum_stock INT NOT NULL DEFAULT 0,PRIMARY KEY(variant_id,warehouse_id),FOREIGN KEY(variant_id) REFERENCES variants(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),CHECK(on_hand>=0),CHECK(quarantine>=0),CHECK(safety_stock>=0),CHECK(minimum_stock>=0)) ENGINE=InnoDB;
CREATE TABLE inventory_lots(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY DEFAULT(UUID()),variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,lot_number VARCHAR(191) COLLATE utf8mb4_bin NOT NULL,expires_at DATE,recall_reference TEXT,quarantined BOOLEAN NOT NULL DEFAULT false,source_reference TEXT NOT NULL DEFAULT(''),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(variant_id,lot_number),UNIQUE(id,variant_id),FOREIGN KEY(variant_id) REFERENCES variants(id),CHECK(quarantined IN(0,1))) ENGINE=InnoDB;
CREATE TABLE inventory_movements(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY DEFAULT(UUID()),variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,warehouse_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,type VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,quantity INT NOT NULL,quarantine_quantity INT NOT NULL DEFAULT 0,reason TEXT NOT NULL,reference VARCHAR(255) COLLATE utf8mb4_bin UNIQUE,actor_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,lot_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(id,variant_id,lot_id),FOREIGN KEY(variant_id) REFERENCES variants(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(lot_id) REFERENCES inventory_lots(id)) ENGINE=InnoDB;
CREATE TABLE inventory_lot_balances(lot_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,warehouse_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,on_hand INT NOT NULL DEFAULT 0,quarantine INT NOT NULL DEFAULT 0,PRIMARY KEY(lot_id,warehouse_id),FOREIGN KEY(lot_id) REFERENCES inventory_lots(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),CHECK(on_hand>=0),CHECK(quarantine>=0)) ENGINE=InnoDB;
CREATE TABLE bundle_components(bundle_variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,component_variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,quantity INT NOT NULL,PRIMARY KEY(bundle_variant_id,component_variant_id),FOREIGN KEY(bundle_variant_id) REFERENCES variants(id),FOREIGN KEY(component_variant_id) REFERENCES variants(id),CHECK(quantity>0),CHECK(bundle_variant_id<>component_variant_id)) ENGINE=InnoDB;
CREATE TABLE commerce_sequences(name VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,next_value BIGINT NOT NULL DEFAULT 0,CHECK(next_value>=0)) ENGINE=InnoDB;
INSERT INTO commerce_sequences(name,next_value) VALUES('order',0);
CREATE TABLE orders(
 id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY DEFAULT(UUID()),number VARCHAR(100) COLLATE utf8mb4_bin NOT NULL UNIQUE DEFAULT '',
 cart_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,user_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,
 idempotency_key VARCHAR(191) COLLATE utf8mb4_bin NOT NULL,request_hash VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,tracking_hash VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 status VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'awaiting_payment',payment_status VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending',fulfillment_status VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'unfulfilled',
 currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,subtotal_minor BIGINT NOT NULL,discount_minor BIGINT NOT NULL DEFAULT 0,shipping_minor BIGINT NOT NULL,tax_minor BIGINT NOT NULL,total_minor BIGINT NOT NULL,
 cost_minor BIGINT NOT NULL DEFAULT 0,fee_minor BIGINT NOT NULL DEFAULT 0,advertising_minor BIGINT NOT NULL DEFAULT 0,return_provision_minor BIGINT NOT NULL DEFAULT 0,
 email VARCHAR(320) COLLATE utf8mb4_bin NOT NULL,address JSON NOT NULL,locale VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'tr',snapshot JSON NOT NULL,
 expires_at DATETIME(3) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),address_profile_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,
 UNIQUE(cart_id,idempotency_key),FOREIGN KEY(cart_id) REFERENCES carts(id),FOREIGN KEY(address_profile_id) REFERENCES country_address_profiles(id),CHECK(total_minor>=0)
) ENGINE=InnoDB;
CREATE TABLE order_fulfillment_groups(
 id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY DEFAULT(UUID()),order_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,supplier_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,
 status VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'awaiting_payment',snapshot JSON NOT NULL,external_reference TEXT,decision_reason TEXT,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 warehouse_order VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS(CASE WHEN source='warehouse' THEN order_id ELSE NULL END) VIRTUAL,
 UNIQUE(id,order_id),UNIQUE(order_id,supplier_id),UNIQUE(warehouse_order),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(supplier_id) REFERENCES suppliers(id),
 CHECK(source IN('warehouse','supplier')),CHECK(status IN('awaiting_payment','ready','accepted','partially_shipped','shipped','cancelled','exception')),CHECK((source='supplier' AND supplier_id IS NOT NULL) OR(source='warehouse' AND supplier_id IS NULL))
) ENGINE=InnoDB;
CREATE TABLE order_items(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY DEFAULT(UUID()),order_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name TEXT NOT NULL,sku VARCHAR(191) COLLATE utf8mb4_bin NOT NULL,quantity INT NOT NULL,unit_minor BIGINT NOT NULL,cost_minor BIGINT NOT NULL,discount_minor BIGINT NOT NULL DEFAULT 0,tax_minor BIGINT NOT NULL DEFAULT 0,snapshot JSON NOT NULL,fulfillment_source VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'warehouse',fulfillment_group_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,UNIQUE(order_id,variant_id),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(variant_id) REFERENCES variants(id),FOREIGN KEY(fulfillment_group_id,order_id) REFERENCES order_fulfillment_groups(id,order_id),CHECK(quantity>0),CHECK(fulfillment_source IN('warehouse','supplier'))) ENGINE=InnoDB;
CREATE TABLE reservations(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY DEFAULT(UUID()),order_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,variant_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,warehouse_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,quantity INT NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'active',expires_at DATETIME(3) NOT NULL,UNIQUE(order_id,variant_id,warehouse_id),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(variant_id) REFERENCES variants(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),CHECK(quantity>0),CHECK(status IN('active','consumed','released','expired')),INDEX reservation_active(variant_id,warehouse_id,status,expires_at)) ENGINE=InnoDB;
CREATE TABLE reservation_lots(reservation_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,lot_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,quantity INT NOT NULL,PRIMARY KEY(reservation_id,lot_id),FOREIGN KEY(reservation_id) REFERENCES reservations(id),FOREIGN KEY(lot_id) REFERENCES inventory_lots(id),CHECK(quantity>0)) ENGINE=InnoDB;
CREATE TABLE payments(id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY DEFAULT(UUID()),order_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,provider VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending',provider_reference VARCHAR(255) COLLATE utf8mb4_bin UNIQUE,amount_minor BIGINT NOT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,refunded_minor BIGINT NOT NULL DEFAULT 0,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE payment_events(id VARCHAR(200) COLLATE utf8mb4_bin PRIMARY KEY,payment_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,payload_hash VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(payment_id) REFERENCES payments(id)) ENGINE=InnoDB;
DELIMITER $$
CREATE TRIGGER order_number_insert BEFORE INSERT ON orders FOR EACH ROW BEGIN
 DECLARE value BIGINT;
 IF NEW.number='' THEN
  UPDATE commerce_sequences SET next_value=next_value+1 WHERE name='order';
  SELECT next_value INTO value FROM commerce_sequences WHERE name='order';
  SET NEW.number=CONCAT('SG-',LPAD(CAST(value AS CHAR),GREATEST(7,CHAR_LENGTH(CAST(value AS CHAR))),'0'));
 END IF;
END$$
DELIMITER ;
